-- -----------------------------------------------------------------------------
-- Platform audit log: append-only for every role (like audit_logs).
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION platform_audit_logs_block_mutation() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'platform_audit_logs is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;
CREATE TRIGGER platform_audit_logs_append_only
  BEFORE UPDATE OR DELETE ON platform_audit_logs
  FOR EACH ROW EXECUTE FUNCTION platform_audit_logs_block_mutation();
CREATE TRIGGER platform_audit_logs_no_truncate
  BEFORE TRUNCATE ON platform_audit_logs
  FOR EACH STATEMENT EXECUTE FUNCTION platform_audit_logs_block_mutation();

-- -----------------------------------------------------------------------------
-- Tenant purge authorisation. The append-only ledgers (audit_logs,
-- folio_entries, guest_invoices, receipts) refuse UPDATE and DELETE for every
-- role. Two legitimate deletions exist: the NDPA offboarding deletion after the
-- 30-day grace, and purging the stale shared copy of a tenant that moved to a
-- dedicated database. `app_begin_tenant_purge(tenant)` (hotel_platform only)
-- checks that one of them is under way for that tenant and records the
-- current transaction id; the triggers then let DELETE (never UPDATE) of that
-- tenant's rows through, inside that transaction only.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_private.tenant_purges (
  tenant_id  uuid        NOT NULL,
  txid       bigint      NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, txid)
);
REVOKE ALL ON app_private.tenant_purges FROM PUBLIC;

CREATE OR REPLACE FUNCTION app_private.purge_allowed(p_tenant uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
AS $$
  SELECT p_tenant IS NOT NULL AND EXISTS (
    SELECT 1 FROM app_private.tenant_purges WHERE tenant_id = p_tenant AND txid = txid_current()
  )
$$;
REVOKE ALL ON FUNCTION app_private.purge_allowed(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_private.purge_allowed(uuid) TO hotel_app, hotel_platform;

CREATE OR REPLACE FUNCTION app_begin_tenant_purge(p_tenant uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT (
    EXISTS (SELECT 1 FROM tenant_offboardings WHERE tenant_id = p_tenant AND status = 'DELETING')
    OR EXISTS (SELECT 1 FROM tenant_databases WHERE tenant_id = p_tenant AND mode = 'DEDICATED' AND status = 'ACTIVE')
  ) THEN
    RAISE EXCEPTION 'tenant % is not being purged', p_tenant USING ERRCODE = 'insufficient_privilege';
  END IF;
  DELETE FROM app_private.tenant_purges WHERE created_at < now() - interval '1 day';
  INSERT INTO app_private.tenant_purges (tenant_id, txid) VALUES (p_tenant, txid_current())
    ON CONFLICT DO NOTHING;
END
$$;
REVOKE ALL ON FUNCTION app_begin_tenant_purge(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_begin_tenant_purge(uuid) TO hotel_platform;

CREATE OR REPLACE FUNCTION audit_logs_block_mutation() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  -- Nested IF: PL/pgSQL does not short-circuit AND, and OLD is unset for TRUNCATE.
  IF TG_OP = 'DELETE' THEN
    IF app_private.purge_allowed(OLD.tenant_id) THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'audit_logs is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE OR REPLACE FUNCTION folio_entries_block_mutation() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  -- Nested IF: PL/pgSQL does not short-circuit AND, and OLD is unset for TRUNCATE.
  IF TG_OP = 'DELETE' THEN
    IF app_private.purge_allowed(OLD.tenant_id) THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION '% is append-only: % is not allowed (post a VOID entry instead)', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;

GRANT DELETE ON audit_logs, folio_entries, guest_invoices, receipts TO hotel_platform;

-- -----------------------------------------------------------------------------
-- RLS on the new tables.
--   Tenant-scoped control-plane tables (hotel reads them through a signed
--   tenant context on the shared database) and the data-plane webhook tables:
--   tenant_isolation for hotel_app, platform_access for hotel_platform.
--   Platform-only tables: RLS on with platform_access only; hotel_app has no
--   grants at all.
-- -----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'coupon_redemptions', 'announcement_receipts', 'support_requests', 'support_messages', 'support_attachments',
    'impersonation_sessions', 'data_exports', 'api_keys', 'api_usage_daily', 'white_label_settings',
    'email_domains', 'sms_sender_requests', 'staff_portal_domains', 'sso_configs',
    'webhook_endpoints', 'webhook_deliveries'
  ]
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO hotel_app
         USING (tenant_id = (SELECT app_current_tenant_id()))
         WITH CHECK (tenant_id = (SELECT app_current_tenant_id()))', t);
    EXECUTE format(
      'CREATE POLICY platform_access ON %I FOR ALL TO hotel_platform
         USING (true) WITH CHECK (true)', t);
  END LOOP;

  FOREACH t IN ARRAY ARRAY[
    'platform_recovery_codes', 'platform_sessions', 'platform_refresh_tokens', 'platform_audit_logs',
    'coupons', 'announcements', 'tenant_offboardings', 'tenant_databases', 'db_provisionings',
    'public_listings', 'job_runs', 'owner_setup_tokens'
  ]
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY platform_access ON %I FOR ALL TO hotel_platform
         USING (true) WITH CHECK (true)', t);
  END LOOP;
END
$$;

