  platform_recovery_codes, platform_sessions, platform_refresh_tokens,
  coupons, coupon_redemptions, announcements, announcement_receipts,
  support_requests, support_messages, support_attachments, impersonation_sessions,
  tenant_offboardings, data_exports, tenant_databases, db_provisionings, public_listings,
  job_runs, owner_setup_tokens, api_keys, api_usage_daily,
  white_label_settings, email_domains, sms_sender_requests, staff_portal_domains, sso_configs,
  webhook_endpoints, webhook_deliveries
TO hotel_platform;
GRANT SELECT, INSERT ON platform_audit_logs TO hotel_platform;

-- -----------------------------------------------------------------------------
-- Dedicated-database cutover gate. Every tenant transaction on this database
-- starts with `app_tenant_gate(tenant)`: it takes a shared advisory lock for
-- the tenant (so the cutover can wait for in-flight transactions to drain by
-- taking the exclusive lock once) and says whether the tenant's data is
-- still served here: 'ok', 'read_only' (cutover window: the API rolls back
-- any transaction that wrote) or 'moved' (served by its dedicated database;
-- the API answers 409 TENANT_MIGRATING and refreshes its routing).
-- In a dedicated database tenant_databases is empty, so the answer is 'ok'.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app_tenant_gate(p_tenant uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_temp
AS $$
DECLARE
  v_mode text;
  v_status text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('tenant-gate:' || p_tenant::text, 0));
  SELECT mode, status INTO v_mode, v_status FROM tenant_databases WHERE tenant_id = p_tenant;
  IF v_mode = 'DEDICATED' AND v_status = 'ACTIVE' THEN
    RETURN 'moved';
  ELSIF v_status = 'CUTOVER' THEN
    RETURN 'read_only';
  END IF;
  RETURN 'ok';
END
$$;
REVOKE ALL ON FUNCTION app_tenant_gate(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_tenant_gate(uuid) TO hotel_app, hotel_platform;
